describe('Breadcrumbs Navigation', () => {
  beforeEach(() => {
    cy.visit('/products');
  });

  it('should display breadcrumbs showing current location in site hierarchy', () => {
    // Verify breadcrumbs container is visible
    cy.get('[data-testid="breadcrumbs-container"]').should('be.visible');

    // Verify breadcrumb links exist
    cy.get('[data-testid="breadcrumb-link"]').should('have.length.greaterThan', 1);

    // Verify breadcrumb structure and text
    cy.get('[data-testid="breadcrumb-link"]').first().should('contain', 'Home');
    cy.get('[data-testid="breadcrumb-link"]').eq(1).should('contain', 'Products');
    cy.get('[data-testid="breadcrumb-link"]').eq(2).should('contain', 'Electronics');
    cy.get('[data-testid="breadcrumb-link"]').eq(3).should('contain', 'Smartphones');

    // Verify current page indicator is present and not a link
    cy.get('[data-testid="breadcrumb-current-page"]').should('be.visible');
    cy.get('[data-testid="breadcrumb-current-page"]').should('contain', 'Smartphones');
    cy.get('[data-testid="breadcrumb-current-page"]').should('not.have.attr', 'href');

    // Verify breadcrumb separator is present
    cy.get('[data-testid="breadcrumb-separator"]').should('be.visible');
  });

  it('should handle deep navigation and display all hierarchy levels', () => {
    // Navigate to a deeply nested page
    cy.get('[data-testid="breadcrumb-link"]').eq(2).click();
    cy.get('[data-testid="breadcrumb-link"]').eq(3).click();
    cy.get('[data-testid="breadcrumb-link"]').eq(4).click();

    // Verify breadcrumbs updated to reflect new location
    cy.get('[data-testid="breadcrumb-link"]').first().should('contain', 'Home');
    cy.get('[data-testid="breadcrumb-link"]').eq(1).should('contain', 'Products');
    cy.get('[data-testid="breadcrumb-link"]').eq(2).should('contain', 'Electronics');
    cy.get('[data-testid="breadcrumb-link"]').eq(3).should('contain', 'Smartphones');
    cy.get('[data-testid="breadcrumb-link"]').eq(4).should('contain', 'Accessories');

    // Verify current page indicator is updated
    cy.get('[data-testid="breadcrumb-current-page"]').should('contain', 'Accessories');

    // Verify breadcrumbs are still clickable except for the current page
    cy.get('[data-testid="breadcrumb-link"]').first().should('be.attr', 'href');
    cy.get('[data-testid="breadcrumb-link"]').eq(1).should('be.attr', 'href');
    cy.get('[data-testid="breadcrumb-link"]').eq(2).should('be.attr', 'href');
    cy.get('[data-testid="breadcrumb-link"]').eq(3).should('be.attr', 'href');
    cy.get('[data-testid="breadcrumb-current-page"]').should('not.have.attr', 'href');
  });
});
